"use strict";
const $=(s,r=document)=>r.querySelector(s), $$=(s,r=document)=>[...r.querySelectorAll(s)];
let runtimeRule=0;function runtimeStyle(el,property,value){if(!el)return;const allowed=new Set(["left","top","width","flex-grow"]);if(!allowed.has(property)||!/^[a-zA-Z0-9 .%+-]+$/.test(String(value)))throw new Error("unsafe runtime style");const cls="rt"+(++runtimeRule),sheet=[...document.styleSheets].find(s=>s.href&&s.href.endsWith("/runtime.css"));if(!sheet)throw new Error("runtime stylesheet unavailable");sheet.insertRule("."+cls+"{"+property+":"+value+"!important}",sheet.cssRules.length);el.classList.add(cls);}
function setDisplay(el,value){if(!el)return;el.classList.remove("d-none","d-block","d-flex","d-inline");el.classList.add(value==="none"?"d-none":value==="flex"?"d-flex":value==="inline-block"?"d-inline":"d-block");}
function isHidden(el){return !el||getComputedStyle(el).display==="none";}
const store={get(k,d){try{const v=localStorage.getItem(k);return v==null?d:v}catch(e){return d}},set(k,v){try{localStorage.setItem(k,v)}catch(e){}}};
function toast(m,kind=""){const t=$("#toast");t.textContent=m;t.className="toast show"+(kind?" "+kind:"");clearTimeout(t._t);t._t=setTimeout(()=>{t.className="toast";},1900);}
function esc(s){return String(s).replace(/&/g,"&amp;").replace(/</g,"&lt;").replace(/>/g,"&gt;");}

