 binary:{label:"Binary / firmware",svg:'<path d="M9 3v18M15 3v18M4 8h16M4 16h16"/>',ext:["bin","elf","hex","img","fw","rom"]},
 pcap:{label:"Network capture",emoji:"\u{1F578}\u{FE0F}",ext:["pcap","pcapng","cap"]},
 doc:{label:"Document",emoji:"\u{1F4C4}",ext:["md","txt","pdf","csv","log"]}
