  $("#ef_save").onclick=()=>{if(!$("#ef_sev").value){toast("Complete CVSS impact metrics before saving");return;}let paragraphs,customFields;try{paragraphs=JSON.parse($("#ef_paragraphs").value||"[]");customFields=JSON.parse($("#ef_customfields").value||"[]");if(!Array.isArray(paragraphs)||!Array.isArray(customFields))throw new Error();}catch(e){toast("Paragraphs and custom fields must be JSON arrays");return;}f.title=$("#ef_title").value.trim()||f.title;f.sev=$("#ef_sev").value;f.vulnType=$("#ef_vt").value.trim();f.target=$("#ef_target").value.trim()||"-";f.status=$("#ef_status").value;f.cvss=$("#ef_cvss").value.trim();f.cvssv4=$("#ef_cvssv4").value.trim();f.category=$("#ef_category").value.trim();f.priority=+$("#ef_priority").value;f.remediationComplexity=+$("#ef_remcomplex").value;f.description=richFindingValue("ef_desc");f.observation=richFindingValue("ef_obs");f.remediation=richFindingValue("ef_rem");f.references=$("#ef_ref").value;f.poc=richFindingValue("ef_poc");f.retestStatus=$("#ef_retest").value;f.retestDescription=$("#ef_retestdesc").value;f.paragraphs=paragraphs;f.customFields=customFields;
    if(online){B.SaveFinding(editMission,f).then(()=>loadFindings(editMission)).then(()=>{$("#findModal").classList.remove("open");renderDock();toast("Finding saved");}).catch(e=>toast("Save failed: "+((e&&e.message)||e)));return;}
    $("#findModal").classList.remove("open");renderDock();toast("Finding saved");};
