function pasteImageInto(e,ta){const items=(e.clipboardData||{}).items||[];for(const it of items){if(it.type&&it.type.indexOf("image")===0){const file=it.getAsFile();if(file){const r=new FileReader();r.onload=()=>insertAtCursor(ta,(ta.value?"\n":"")+"![pasted]("+r.result+")\n");r.readAsDataURL(file);e.preventDefault();}}}}
