/* ---------- backend bridge (Wails bindings; graceful mock fallback) ---------- */
// Wails injects window.go asynchronously, so detect it (and re-detect on a short
// poll) rather than snapshotting once - otherwise the app locks into mock mode.
let B=null, online=false;
let MISSION_TEMPLATES=[];
let CONTAINER_PROFILES=[],CONTAINER_DEFAULTS=null;
let pullEventsBound=false,pullLayers={},pullDisplayedPct=0;
function resetPullProgress(){pullLayers={};pullDisplayedPct=0;runtimeStyle($("#cm_pullbar"),"width","0%");}
function bindPullEvents(){if(pullEventsBound||!window.runtime||!window.runtime.EventsOn)return;pullEventsBound=true;window.runtime.EventsOn("rfswift:image-pull",p=>{const wrap=$("#cm_pullwrap"),bar=$("#cm_pullbar"),status=$("#cm_pullstatus");setDisplay(wrap,"block");if(p.layer)pullLayers[p.layer]={current:p.current||0,total:p.total||0,status:p.status||""};const layers=Object.values(pullLayers),known=layers.filter(x=>x.total>0),current=known.reduce((n,x)=>n+x.current,0),total=known.reduce((n,x)=>n+x.total,0),done=layers.filter(x=>/complete|pull complete|already exists/i.test(x.status)).length,raw=total>0?Math.round(current*100/total):0;pullDisplayedPct=Math.max(pullDisplayedPct,Math.min(95,raw));runtimeStyle(bar,"width",pullDisplayedPct+"%");status.textContent="Downloading · "+done+"/"+layers.length+" layers complete"+(total>0?" · "+Math.round(current/1048576)+" / "+Math.round(total/1048576)+" MB":"");});}
let auditEventsBound=false;function bindAuditEvents(){if(auditEventsBound||!window.runtime||!window.runtime.EventsOn)return;auditEventsBound=true;window.runtime.EventsOn("rfswift:audit-progress",p=>{if(!p||p.mission!==curMission)return;const wrap=$("[data-auditprogress]"),fill=$("[data-auditfill]"),stage=$("[data-auditstage]");if(wrap)wrap.classList.add("open");if(fill)runtimeStyle(fill,"width",Math.max(0,Math.min(100,p.percent||0))+"%");if(stage)stage.textContent=(p.stage||"Auditing")+" · "+(p.percent||0)+"%";});}
function detectBackend(){const app=window.go?.workbench?.App||window.go?.main?.App;if(app){B=app;online=true;bindPullEvents();bindAuditEvents();return true;}return false;}
detectBackend();
function _rerender(){renderRail();renderMissionBar();renderDock();}
async function hydrateBackendState(){
  try{MISSION_TEMPLATES=await B.MissionTemplates()||[];renderMissionTemplates();}catch(e){console.error("MissionTemplates",e);}
  try{CONTAINER_DEFAULTS=await B.ContainerDefaults();CONTAINER_PROFILES=await B.ContainerProfiles()||[];renderContainerProfiles();}catch(e){console.error("Container defaults/profiles",e);}
  try{backendAICfg=await B.GetAgentCfg();agentClients=await B.AgentClients()||[];renderAIChip();}catch(e){console.error("AgentConfig",e);}
  try{const ts=await B.BuiltinCaptureTypes();for(const t of (ts||[])){const old=BUILTIN_TYPES[t.key]||{};BUILTIN_TYPES[t.key]={label:t.label,ext:t.exts||[],svg:old.svg,emoji:old.emoji};}}catch(e){console.error("BuiltinCaptureTypes",e);}
  try{const ts=await B.CustomCaptureTypes();backendCustomTypes={};for(const t of (ts||[])){backendCustomTypes[t.key]={label:t.label,ext:t.exts||[],emoji:t.icon||"📎"};}}catch(e){console.error("CustomCaptureTypes",e);}
  try{const ws=await B.CurrentWorkspace();$("#workspaceBtn").textContent="project: "+ws+" ▾";}catch(e){console.error("CurrentWorkspace",e);}
  try{const cs=await B.Connections();if(cs&&cs.length){CONNECTIONS=cs;if(!CONNECTIONS.some(c=>c.id===curConn))curConn=cs[0].id;for(const c of cs){try{const a=await B.AuditConn(c.id);CONN_AUDITS[c.id]={posture:a.posture,checks:(a.checks||[]).map(x=>({s:x.severity,l:x.label,d:x.detail,r:x.rec}))};}catch(e){console.error("AuditConn",e);}}renderConnChip();}}catch(e){console.error("Connections",e);}
}
function mapMission(g){return {id:g.id,title:g.title||g.id,engine:g.engine,env:g.env||"",flakeRef:g.flakeRef||"",up:g.status==="up",starting:g.status==="starting",image:g.image||"",user:g.user||"root",caps:g.caps||[],cgroups:g.cgroups||[],mounts:g.mounts||[],net:g.net||"",ports:(g.ports||[]).map(p=>[p.port,p.published,p.service]),desktopURL:g.desktopURL||"",environmentAudit:g.environmentAudit||g.posture||{crit:0,high:0,med:0,low:0},auditIssues:g.auditIssues||[],findingSummary:g.findingSummary||{crit:0,high:0,med:0,low:0},cnote:g.notes||"",note:"",console:[],ai:[]};}
async function hydrateMissions(){try{const gs=await B.Missions();MISSIONS.length=0;(gs||[]).forEach(g=>MISSIONS.push(mapMission(g)));}catch(e){console.error("Missions",e);toast("Target refresh failed");}
  if(!mission(curMission)&&MISSIONS[0])curMission=MISSIONS[0].id;_rerender();if(mission(curMission))selectMissionData(curMission);}
async function hydrateInspect(id){const m=mission(id);if(!m)return;try{const g=await B.InspectMission(id);if(g&&g.id){m.user=g.user||m.user;m.caps=g.caps||m.caps;m.cgroups=g.cgroups||[];m.mounts=g.mounts||m.mounts;m.net=g.net||m.net;m.image=g.image||m.image;m.env=g.env||m.env;m.desktopURL=g.desktopURL||"";m.ports=(g.ports||[]).map(p=>[p.port,p.published,p.service]);}}catch(e){}}
function findingCounts(){const p={crit:0,high:0,med:0,low:0};for(const f of FINDINGS){const s=f.sev==="critical"?"crit":f.sev==="medium"?"med":f.sev;if(p[s]!=null)p[s]++;}return p;}
async function loadFindings(id){try{const fs=await B.ListFindings(id);FINDINGS.length=0;(fs||[]).forEach(f=>FINDINGS.push(ensureFindingFields(f)));const m=mission(id);if(m)m.findingSummary=findingCounts();}catch(e){FINDINGS.length=0;}}
async function loadCaptures(id){try{const cs=await B.ListCaptures(id);CAPTURES.length=0;(cs||[]).forEach(c=>CAPTURES.push(c));}catch(e){CAPTURES.length=0;}}
async function selectMissionData(id){if(!online)return;const m=mission(id);if(m){try{m.note=await B.GetNote(id,"note.md")||"";}catch(e){}}
  await hydrateInspect(id);await loadFindings(id);await loadCaptures(id);renderDock();}
function persistNote(m,v){m.note=v;if(online){B.SaveNote(m.id,"note.md",v).catch(()=>{});}else{store.set("note:"+m.id,v);}}
const _noteVal=noteVal;noteVal=function(m){return online?(m.note||""):_noteVal(m);};
const _download=download;download=function(name,content){if(online){return B.SaveFileDialog(name,content).then(p=>{toast(p?("Saved "+p):"Canceled");}).catch(()=>toast("Save failed"));}return _download(name,content);};
const _startMission=startMission;startMission=function(m){if(!online)return _startMission(m);m.starting=true;m.stopping=false;_rerender();return B.StartMission(m.id).then(()=>{m.starting=false;m.up=true;_rerender();toast("Started "+m.id);}).catch(e=>{m.starting=false;_rerender();toast("Start failed: "+((e&&e.message)||e));});};
const _stopMission=stopMission;stopMission=function(m){if(!online)return _stopMission(m);m.stopping=true;_rerender();return B.StopMission(m.id).then(()=>{m.up=false;m.starting=false;m.stopping=false;_rerender();toast("Stopped "+m.id);}).catch(e=>{m.stopping=false;_rerender();toast("Stop failed: "+((e&&e.message)||e));});};
let statusRefreshBusy=false;async function refreshMissionStatuses(){if(!online||statusRefreshBusy)return;statusRefreshBusy=true;try{const states=await B.MissionStatuses();let changed=false;for(const m of MISSIONS){if(m.engine==="nix"||m.starting||m.stopping||states[m.id]==null)continue;const up=states[m.id]==="up";if(m.up!==up){m.up=up;changed=true;}}if(changed)_rerender();}catch(e){}finally{statusRefreshBusy=false;}}
setInterval(refreshMissionStatuses,4000);
const refreshTargets=$("#refreshTargets");if(refreshTargets)refreshTargets.onclick=()=>{if(!online){toast("Backend not connected");return;}toast("Refreshing targets ...");hydrateMissions().then(()=>toast("Targets refreshed"));};
