function dangerConfirm({title,target,message,action}){return new Promise(resolve=>{const modal=$("#dangerModal"),done=value=>{modal.classList.remove("open");resolve(value);};$("#dangerTitle").textContent=title;$("#dangerTarget").textContent=target;$("#dangerMessage").textContent=message;$("#dangerConfirm").textContent=action;$("#dangerConfirm").onclick=()=>done(true);$("#dangerCancel").onclick=()=>done(false);$("#dangerClose").onclick=()=>done(false);modal.onclick=e=>{if(e.target===modal)done(false);};modal.classList.add("open");setTimeout(()=>$("#dangerCancel").focus(),0);});}
