$("#ctxInstall").onclick=()=>{missionContext.classList.remove("open");installerMission=contextMission;if(!installerMission)return;$("#installerTarget").textContent=installerMission.id+" · "+(installerMission.engine==="nix"?"persistent Nix profile":"container install scripts");setDisplay($("#installerAllWrap"),installerMission.engine==="nix"?"block":"none");$("#installerAll").checked=false;$("#installerQuery").value="";$("#installerResults").innerHTML="";$("#installerDetail").textContent=installerMission.engine==="nix"?"Search RF Swift tools, or enable all nixpkgs for packages outside the catalog.":"Search installer functions discovered directly inside this container.";$("#installerInstall").disabled=true;$("#installerModal").classList.add("open");setTimeout(()=>$("#installerQuery").focus(),0);};
$("#installerSearch").onclick=async()=>{if(!installerMission)return;const btn=$("#installerSearch"),results=$("#installerResults");btn.disabled=true;btn.textContent="Searching…";results.innerHTML="";$("#installerDetail").textContent="Discovering tools on "+installerMission.id+"…";try{installerTools=await B.SearchMissionTools(installerMission.id,$("#installerQuery").value.trim(),installerMission.engine==="nix"&&$("#installerAll").checked)||[];results.innerHTML=installerTools.map((x,i)=>`<option value="${i}">${esc(x.name)} · ${esc(x.source||"")}</option>`).join("");$("#installerDetail").textContent=installerTools.length?installerTools.length+" tool(s) found. Select one to see details.":"No matching tool was found.";}catch(e){$("#installerDetail").textContent="Search failed: "+((e&&e.message)||e);}finally{btn.disabled=false;btn.textContent="Search";}};
