$("#ctxDelete").onclick=async()=>{missionContext.classList.remove("open");const m=contextMission;if(!m)return;const nix=m.engine==="nix",message=nix?"This removes its manifest, lazy shims and GC root. Its workspace, findings and notes are preserved. Store paths are not reclaimed until garbage collection.":"This stops all processes and force-removes the writable container layer. Data stored only in that layer can be lost.\n\nPreserved: named volumes, bind-mounted workspace files, images, findings and notes.";if(!await dangerConfirm({title:nix?"Remove Nix environment?":"Delete container?",target:m.id,message,action:nix?"Remove environment":"Delete container"}))return;try{if(nix)await B.DeleteNixEnvironment(m.id,false);else await B.DeleteContainer(m.id);await hydrateMissions();toast((nix?"Removed environment ":"Deleted container ")+m.id+"; workspace data was preserved");}catch(e){toast("Delete failed: "+((e&&e.message)||e));}};
