function applyContainerDefaults(){const d=CONTAINER_DEFAULTS||{};$("#cm_image").value=simpleImageName(d.image||"");$("#cm_bindings").value=(d.bindings||[]).join("\n");$("#cm_devices").value=(d.devices||[]).join("\n");$("#cm_cgroups").value=(d.cgroupRules||[]).join(", ");$("#cm_exposed").value=d.exposedPorts||"";$("#cm_ports").value=d.portBindings||"";$("#cm_seccomp").value=d.seccomp||"";$("#cm_network").value=d.network||"host";const known=new Set($$('[data-cmcap]').map(x=>x.dataset.cmcap)),caps=d.caps||[];$("#cm_caps").value=caps.filter(x=>!known.has(x)).join(",");$$('[data-cmcap]').forEach(x=>x.checked=caps.includes(x.dataset.cmcap));$("#cm_priv").checked=!!d.privileged;$("#cm_desktop").checked=!!d.desktopProto;$("#cm_desktopproto").value=d.desktopProto||"http";$("#cm_desktophost").value=d.desktopHost||"127.0.0.1";$("#cm_desktopport").value=d.desktopPort||"6080";$("#cm_desktoppass").value=d.desktopPassword||"";$("#cm_desktopssl").checked=!!d.desktopSSL;$("#cm_network").onchange();$("#cm_desktop").onchange();updateContainerImageHint();}
function resetContainerCreateForm(){$("#cm_profile").value="";for(const id of ["#cm_workspace","#cm_gpucustom"]){const el=$(id);if(el)el.value="";}$("#cm_gpus").value="";$("#cm_realtime").checked=false;$("#cm_x11").checked=true;applyContainerDefaults();$("#cm_profilehint").textContent=CONTAINER_DEFAULTS?.path?"Base defaults: "+CONTAINER_DEFAULTS.path:"RF-Swift platform defaults";$("#cm_gpus").onchange();}
if(cmOpen)cmOpen.onclick=()=>{if(!online){toast("Backend not connected");return;}renderMissionTemplates();renderContainerProfiles();resetContainerCreateForm();$("#cm_create").textContent=targetScope==="nix"?"Create environment":"Create container";$("#cm_name").value="";$("#cm_title").value="";cmEngine.value=targetScope==="nix"?"nix":"docker";cmEngine.onchange();cmModal.classList.add("open");};
$("#missionClose").onclick=()=>cmModal.classList.remove("open");cmModal.addEventListener("click",e=>{if(e.target===cmModal)cmModal.classList.remove("open");});
cmEngine.onchange=()=>{const nix=cmEngine.value==="nix";setDisplay($("#cm_template"),nix?"block":"none");setDisplay($("#cm_image"),nix?"none":"block");setDisplay($("#cm_nix"),nix?"flex":"none");setDisplay($("#cm_container"),nix?"none":"block");if(nix)$("#cm_hint").textContent=(MISSION_TEMPLATES.find(x=>x.name===$("#cm_template").value)||{}).description||"";else updateContainerImageHint();};
$("#cm_template").oninput=()=>{const t=MISSION_TEMPLATES.find(x=>x.name===$("#cm_template").value);$("#cm_hint").textContent=t?t.description:"Unknown Nix environment name";};
$("#cm_network").onchange=()=>$$('.cm_nat').forEach(x=>setDisplay(x,$("#cm_network").value==="nat"?"flex":"none"));
$("#cm_gpus").onchange=()=>setDisplay($("#cm_gpucustom"),$("#cm_gpus").value==="custom"?"block":"none");
$("#cm_desktop").onchange=()=>setDisplay($("#cm_desktopopts"),$("#cm_desktop").checked?"block":"none");
$("#cm_desktopproto").onchange=()=>$("#cm_desktopport").value=$("#cm_desktopproto").value==="vnc"?"5900":"6080";
$("#cm_desktophost").onchange=()=>{const pub=$("#cm_desktophost").value==="0.0.0.0";$("#cm_desktopwarn").classList.toggle("danger-text",pub);$("#cm_desktopwarn").textContent=pub?"Warning: reachable from the network. Set a strong password and consider SSL/TLS.":"The selected RF-Swift image must include its desktop scripts. Local-only binding is recommended.";};
$("#cm_flaketype").onchange=()=>{const t=$("#cm_flaketype").value,ref=$("#cm_flakeref");ref.readOnly=t!=="custom";setDisplay($("#cm_flakepick"),t==="local"?"inline-block":"none");if(t==="official")ref.value="github:PentHertz/RF-Swift-nix";if(t==="local")ref.value="";if(t==="custom")ref.readOnly=false;$("#cm_flakehint").textContent=t==="official"?"Uses the published official GitHub flake.":t==="local"?"Select a local RF-Swift-nix checkout containing flake.nix.":"Enter a Nix flake reference such as github:owner/repo, path:/dir, or /dir.";};
$("#cm_flakepick").onclick=()=>B.SelectWorkspaceDirectory().then(p=>{if(p)$("#cm_flakeref").value=p;});
$("#cm_profile").onchange=()=>{const p=CONTAINER_PROFILES.find(x=>x.name===$("#cm_profile").value);applyContainerDefaults();if(!p){$("#cm_profilehint").textContent=CONTAINER_DEFAULTS?.path?"Base defaults: "+CONTAINER_DEFAULTS.path:"RF-Swift platform defaults";return;}$("#cm_profilehint").textContent=(p.description||"")+" · merged with "+(CONTAINER_DEFAULTS?.path||"platform config.ini");if(p.image)$("#cm_image").value=simpleImageName(p.image);updateContainerImageHint();if(p.network){$("#cm_network").value=p.network.startsWith("nat")?"nat":p.network;$("#cm_network").onchange();}for(const item of (p.bindings||"").split(",").filter(Boolean))addUniqueLine("#cm_bindings",item);for(const item of (p.devices||"").split(",").filter(Boolean))addUniqueLine("#cm_devices",item);const profileCaps=(p.caps||"").split(",").map(x=>x.trim()).filter(Boolean),allCaps=[...(CONTAINER_DEFAULTS?.caps||[]),...profileCaps],known=new Set($$('[data-cmcap]').map(x=>x.dataset.cmcap));$("#cm_caps").value=[...new Set(allCaps.filter(x=>!known.has(x)))].join(",");$$('[data-cmcap]').forEach(x=>x.checked=allCaps.includes(x.dataset.cmcap));const rules=[...(CONTAINER_DEFAULTS?.cgroupRules||[]),...(p.cgroups||"").split(",")].map(x=>x.trim()).filter(Boolean);$("#cm_cgroups").value=[...new Set(rules)].join(", ");if(p.exposedPorts)$("#cm_exposed").value=p.exposedPorts;if(p.portBindings)$("#cm_ports").value=p.portBindings;$("#cm_gpus").value=p.gpus||"";$("#cm_gpus").onchange();$("#cm_realtime").checked=!!p.realtime;$("#cm_priv").checked=!!p.privileged;$("#cm_x11").checked=!p.noX11;$("#cm_desktop").checked=!!p.desktop;$("#cm_desktopssl").checked=!!p.desktopSSL;$("#cm_desktop").onchange();};
function profileKey(value){const raw=(value||"").trim().toLowerCase(),tag=raw.includes(":")?raw.slice(raw.lastIndexOf(":")+1):raw.includes("/")?raw.slice(raw.lastIndexOf("/")+1):raw;return tag.replace(/^rfswift[-_]?/,"").replace(/_/g,"-");}
$("#cm_image").oninput=()=>{updateContainerImageHint();const key=profileKey($("#cm_image").value),p=CONTAINER_PROFILES.find(x=>profileKey(x.name)===key||profileKey(x.image)===key);if(!p)return;$("#cm_profile").value=p.name;$("#cm_profile").onchange();toast("Applied RF-Swift profile: "+p.name);};
$("#cm_workspacepick").onclick=()=>B.SelectWorkspaceDirectory().then(p=>{if(p)$("#cm_workspace").value=p;});
function addUniqueLine(field,line){const ta=$(field);if(!ta||!line)return;const norm=x=>x.trim().replace(/:(?:ro|rw)$/i,""),wanted=norm(line);if(!ta.value.split("\n").some(x=>norm(x)===wanted))ta.value+=(ta.value.trim()?"\n":"")+line;}
function addPathLine(field,path,dest){if(!path)return;addUniqueLine(field,path+":"+(dest||path));}
$("#cm_binddir").onclick=async()=>{const p=await B.SelectHostPath(true);if(!p)return;const d=await workbenchDialog({title:"Add directory mount",target:p,inputLabel:"Path inside container",value:p,action:"Add mount"});if(d)addPathLine("#cm_bindings",p,d+":rw");};
$("#cm_bindfile").onclick=async()=>{const p=await B.SelectHostPath(false);if(!p)return;const d=await workbenchDialog({title:"Add file mount",target:p,inputLabel:"Path inside container",value:p,action:"Add mount"});if(d)addPathLine("#cm_bindings",p,d+":rw");};
$("#cm_devicebind").onclick=async()=>{const p=await B.SelectHostPath(false);if(!p)return;const d=await workbenchDialog({title:"Bind device path",target:p,inputLabel:"Device path inside container",value:p,action:"Add binding"});if(d)addPathLine("#cm_bindings",p,d+":rw");};
$("#cm_usbotplug").onclick=()=>{addUniqueLine("#cm_bindings","/dev/bus/usb:/dev/bus/usb:rw");const rules=$("#cm_cgroups").value.split(",").map(x=>x.trim()).filter(Boolean);if(!rules.includes("c 189:* rwm"))rules.push("c 189:* rwm");$("#cm_cgroups").value=rules.join(", ");toast("USB hotplug mount and cgroup rule applied");};
$("#cm_devicepick").onclick=async()=>{const p=await B.SelectHostPath(false);if(!p)return;const d=await workbenchDialog({title:"Map device",target:p,inputLabel:"Device path inside container",value:p,action:"Add device"});if(d)addPathLine("#cm_devices",p,d);};
$("#cm_proxmark").onclick=()=>{addUniqueLine("#cm_devices","/dev/ttyACM0:/dev/ttyACM0");addUniqueLine("#cm_bindings","/dev/bus/usb:/dev/bus/usb:rw");const rules=$("#cm_cgroups").value.split(",").map(x=>x.trim()).filter(Boolean);if(!rules.includes("c 189:* rwm"))rules.push("c 189:* rwm");$("#cm_cgroups").value=rules.join(", ");};
async function pullSelectedImage(mission=""){const engine=cmEngine.value,image=$("#cm_image").value.trim(),btn=$("#cm_pull"),wrap=$("#cm_pullwrap"),bar=$("#cm_pullbar"),status=$("#cm_pullstatus");if(!image)throw new Error("Enter an image name first");btn.disabled=true;btn.textContent="Downloading...";setDisplay(wrap,"block");resetPullProgress();status.textContent="Resolving "+image+" for "+engine+"...";try{const resolved=mission?await B.PullMissionImageForMission(mission,engine,image):await B.PullMissionImage(engine,image);pullDisplayedPct=100;runtimeStyle(bar,"width","100%");status.textContent="Ready: "+simpleImageName(resolved);toast("Image downloaded");return resolved;}catch(e){runtimeStyle(bar,"width","0%");status.textContent="Error: "+((e&&e.message)||e);throw e;}finally{btn.disabled=false;btn.textContent="Download image";}}
$("#cm_pull").onclick=()=>pullSelectedImage().catch(()=>{});
let activeCreationName="",creationStopRequested=false;
$("#cm_create").onclick=async()=>{const btn=$("#cm_create"),status=$("#cm_status");if(activeCreationName){creationStopRequested=true;btn.disabled=true;btn.textContent="Cleaning…";status.textContent="Stopping creation and removing partial resources…";try{await B.CancelMissionCreation(activeCreationName);}catch(e){status.textContent="Cleanup request failed: "+((e&&e.message)||e);}return;}const name=$("#cm_name").value.trim(),isNix=cmEngine.value==="nix";let image=(isNix?$("#cm_template").value:$("#cm_image").value.trim());if(!name||!image){toast("Name and environment/image are required");return;}activeCreationName=name;creationStopRequested=false;btn.classList.add("stopcreate");btn.textContent="Stop & clean";status.textContent=isNix&&!$("#cm_lazy").checked?"Building environment; this may take a while...":"Checking image...";try{await B.BeginMissionCreation(name);if(!isNix){const availability=await B.CheckMissionImage(cmEngine.value,image);if(availability.present&&availability.resolved)image=availability.resolved;if(!availability.present){status.textContent="Image is not local · downloading automatically…";image=(await pullSelectedImage(name))||availability.resolved||image;}else if(availability.updateAvailable){const update=await workbenchDialog({title:"Newer image available",target:simpleImageName(availability.resolved),message:"Download the latest RF-Swift image before creating this mission? You can continue with the installed image instead.",action:"Download update"});if(update)image=(await pullSelectedImage(name))||image;}}status.textContent="Creating target...";const capSet=new Set([...( $("#cm_caps").value.split(",")),...$$('[data-cmcap]:checked').map(x=>x.dataset.cmcap)].map(x=>x.trim()).filter(Boolean)),network=$("#cm_network").value==="nat"?("nat:"+$("#cm_natname").value.trim()+":"+$("#cm_subnet").value.trim()):$("#cm_network").value,gpu=$("#cm_gpus").value==="custom"?$("#cm_gpucustom").value.trim():$("#cm_gpus").value;const lines=id=>$(id).value.split("\n").map(x=>x.trim()).filter(Boolean);const m=await B.CreateMission({name,title:$("#cm_title").value.trim(),engine:cmEngine.value,image,flakeRef:isNix?$("#cm_flakeref").value.trim():"",workspace:$("#cm_workspace").value.trim(),network,caps:[...capSet],bindings:lines("#cm_bindings"),devices:lines("#cm_devices"),exposedPorts:$("#cm_exposed").value.trim(),portBindings:$("#cm_ports").value.trim(),cgroupRules:$("#cm_cgroups").value.split(",").map(x=>x.trim()).filter(Boolean),gpus:gpu,seccomp:$("#cm_seccomp").value.trim(),shell:CONTAINER_DEFAULTS?.shell||"/bin/bash",extraHosts:CONTAINER_DEFAULTS?.extraHosts||[],environment:CONTAINER_DEFAULTS?.environment||[],realtime:$("#cm_realtime").checked,desktop:$("#cm_desktop").checked,desktopProto:$("#cm_desktopproto").value,desktopHost:$("#cm_desktophost").value,desktopPort:$("#cm_desktopport").value.trim(),desktopPassword:$("#cm_desktoppass").value,desktopSSL:$("#cm_desktopssl").checked,noX11:!$("#cm_x11").checked,privileged:$("#cm_priv").checked,start:$("#cm_start").checked,lazy:$("#cm_lazy").checked,pure:$("#cm_pure").checked});if(creationStopRequested)throw new Error("creation canceled");cmModal.classList.remove("open");await hydrateMissions();if(m&&m.id){curMission=m.id;await selectMissionData(m.id);_rerender();}toast("Mission "+name+" created");}catch(e){status.textContent=creationStopRequested?"Creation stopped · partial resources cleaned":"Error: "+((e&&e.message)||e);}finally{await B.FinishMissionCreation(name).catch(()=>{});activeCreationName="";creationStopRequested=false;btn.disabled=false;btn.classList.remove("stopcreate");btn.textContent=isNix?"Create environment":"Create container";}};
const workspaceBtn=$("#workspaceBtn");
async function switchProject(name){const current=await B.CurrentWorkspace();if(!name||name===current)return;await B.OpenWorkspace(name);workspaceBtn.textContent="project: "+name+" ▾";$("#projectModal").classList.remove("open");curMission="";await hydrateMissions();toast("Closed "+current+" and opened "+name);}
async function renderProjectSwitcher(){
 if(!online){toast("Projects require the desktop app");return;}
 const current=await B.CurrentWorkspace(),names=await B.Workspaces()||[];
 $("#projectBody").innerHTML=`<div class="project-current"><div class="u107"><b>${esc(current)}</b><span class="spacer"></span><button class="btn ghost sm" id="projectCloseCurrent">Close project</button></div><small>Current project · notes and findings are autosaved. Closing returns to the default project and does not stop containers or VMs.</small></div><b class="u88">Projects</b><div class="project-list">${names.map(n=>`<div class="project-row ${n===current?"current":""}"><span>${esc(n)}</span><span class="spacer"></span>${n===current?'<small>open</small>':`<button class="btn ghost sm" data-project="${esc(n)}">Open</button><button class="btn ghost sm u30" data-projectdelete="${esc(n)}">Delete</button>`}</div>`).join("")||'<div class="empty">No projects yet.</div>'}</div><b class="u88">Create or open by name</b><div class="u108"><input id="projectName" placeholder="project-name" class="u10"><button class="btn sm" id="projectOpenName">Open</button></div><div class="u109"><button class="btn ghost sm" id="projectImport">Import archive…</button><span class="u10"></span><button class="btn ghost sm" id="projectExport">Export current project…</button></div>`;
 $$('[data-project]',$("#projectBody")).forEach(b=>b.onclick=()=>switchProject(b.dataset.project).catch(e=>toast("Project switch failed: "+((e&&e.message)||e))));
 $$('[data-projectdelete]',$("#projectBody")).forEach(b=>b.onclick=async()=>{const name=b.dataset.projectdelete;if(!await dangerConfirm({title:"Delete Workbench project?",target:name,message:"This permanently deletes the project setup, mission notes, findings, reports, captures, and saved terminal recordings stored inside it. Running containers and external bind-mounted files are not deleted. Export the project first if you may need it later.",action:"Delete project"}))return;try{await B.DeleteWorkspace(name);await renderProjectSwitcher();toast("Deleted project "+name);}catch(e){toast("Project deletion failed: "+((e&&e.message)||e));}});
 $("#projectCloseCurrent").onclick=async()=>{try{const fallback=await B.CloseWorkspace();workspaceBtn.textContent="project: "+fallback+" ▾";curMission="";await hydrateMissions();await renderProjectSwitcher();toast("Project closed; opened "+fallback);}catch(e){toast("Project close failed: "+((e&&e.message)||e));}};
 $("#projectOpenName").onclick=()=>switchProject($("#projectName").value.trim()).catch(e=>toast("Project open failed: "+((e&&e.message)||e)));$("#projectName").onkeydown=e=>{if(e.key==="Enter")$("#projectOpenName").click();};
 $("#projectImport").onclick=async()=>{const b=$("#projectImport");b.disabled=true;try{const name=await B.ImportWorkbenchProject();if(name){workspaceBtn.textContent="project: "+name+" ▾";$("#projectModal").classList.remove("open");curMission="";await hydrateMissions();toast("Imported and opened "+name);}}catch(e){toast("Project import failed: "+((e&&e.message)||e));}finally{b.disabled=false;}};
 $("#projectExport").onclick=async()=>{const b=$("#projectExport");b.disabled=true;try{const path=await B.ExportWorkbenchProject();if(path)toast("Project exported to "+path);}catch(e){toast("Project export failed: "+((e&&e.message)||e));}finally{b.disabled=false;}};
}
if(workspaceBtn)workspaceBtn.onclick=()=>{renderProjectSwitcher().then(()=>$("#projectModal").classList.add("open")).catch(e=>toast("Projects failed: "+((e&&e.message)||e)));};
$("#projectClose").onclick=()=>$("#projectModal").classList.remove("open");
$("#projectModal").onclick=e=>{if(e.target.id==="projectModal")$("#projectModal").classList.remove("open");};

/* init */
renderAIChip();renderConnChip();renderRail();renderMissionBar();renderDock();
if(detectBackend()){hydrateBackendState();hydrateMissions();}
else{
  bootAll();
  let _t=0;const _iv=setInterval(()=>{if(detectBackend()){clearInterval(_iv);hydrateBackendState();hydrateMissions();toast("Connected to backend");}else if(++_t>60){clearInterval(_iv);}},50);
}
